                    parsed_prerelease.append((0, int(identifier)))  # 0 for numeric
                else:
                    parsed_prerelease.append((1, identifier))  # 1 for string
        else:
            parsed_prerelease = None

        return (major, minor, patch, prerelease_identifiers if prerelease else [], parsed_prerelease)

    def compare_key(item):
        version, original_index = item
        major, minor, patch, prerelease_ids, parsed_prerelease = parse_version(version)

        # For sorting: (major, minor, patch, has_prerelease, prerelease_comparison, original_index)
        # has_prerelease: False (0) if no prerelease, True (1) if prerelease
        # This ensures versions without prerelease sort after those with prerelease
        if parsed_prerelease is None:
            prerelease_tuple = (1,)  # No prerelease sorts after
        else:
            prerelease_tuple = (0, tuple(parsed_prerelease))  # Has prerelease sorts before

        return (major, minor, patch, prerelease_tuple, original_index)

